  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Slea Head', 'Nejzápadnější mys poloostrova Dingle s bílým krucifixem u silnice a výhledem na divoké Blasketovy ostrovy. Silnice R559 tu vede po římse vytesané do útesu — jedno z nejfotogeničtějších míst celé Wild Atlantic Way. Zastavte na malém odstavném pruhu a nechte si projít hlavou, že dál na západ už je jen Amerika.', 52.0975, -10.4467, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slea%20Head,%20Ireland.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slea%20Head,%20Ireland.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Coumeenole%20Beach%20Dingle%20Peninsula%20Kerry%20Ireland.jpg"}'::text[], 0),
    (v_route, 'Přístaviště Dunquin', 'Ikonické mini-molo Dunquin Pier s klikatou pěšinou spadající serpentinami k moři, odkud vyplouvají lodě na Great Blasket. Patří k nejfotografovanějším místům Irska, zvlášť když po cestičce ženou ovce. Motorku nechte nahoře na parkovišti a sejděte pěšky — stojí to za to.', 52.1247, -10.4603, 'https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A9%20Dh%C3%BAn%20Chaoin%20Dunquin%20Pier.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A9%20Dh%C3%BAn%20Chaoin%20Dunquin%20Pier.jpg"}'::text[], 1),
    (v_route, 'Gallarus Oratory', 'Dokonale zachovalá kamenná modlitebna stará přes tisíc let, vyskládaná bez kapky malty do tvaru obrácené lodi. Považuje se za jednu z nejstarších dochovaných staveb Irska a uvnitř je i po staletích sucho. Krátká zastávka s velkou porcí historie, jen pár minut od hlavního okruhu.', 52.1727, -10.3517, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gallarus%20Oratory.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gallarus%20Oratory.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Gallarus%20Oratory%20-%20oldest%20church%20in%20Ireland%20-%20panoramio.jpg"}'::text[], 2),
    (v_route, 'Průsmyk Conor Pass', 'Nejvyšší horská silnice Irska (456 m) se šplhá z Dingle mezi skalami a ledovcovými jezírky — místy je tak úzká, že se dvě auta nevyhnou, motorka tu má luxusní výhodu. Z vrcholového parkoviště se za jasného dne otevírá výhled na obě strany poloostrova až k zálivu Brandon Bay. Za mlhy a silného větru jeďte extrémně opatrně, povrch bývá vlhký.', 52.1596, -10.2038, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dingle%20Conor%20Pass.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dingle%20Conor%20Pass.JPG"}'::text[], 3),
    (v_route, 'Pláž Inch', 'Pětikilometrová písečná kosa vybíhající do Dingle Bay, kterou proslavil film Ryanova dcera. Surfaři, nekonečný písek a panorama hor Kerry na druhé straně zálivu — perfektní nožky-protáhnout zastávka na zpáteční cestě. U vjezdu na pláž je kavárna s výhledem.', 52.141, -9.977, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20at%20Inch%20in%20Dingle%20Bay%20Kerry%20Ireland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20at%20Inch%20in%20Dingle%20Bay%20Kerry%20Ireland.jpg"}'::text[], 4),
    (v_route, 'Restaurace: The Fish Box (Dingle)', 'Rodinný podnik rybářské rodiny Flannery přímo v centru Dingle — ryby a mořské plody jdou z vlastní lodi rovnou na talíř. Fish & chips, poke bowl i denní úlovek; na Googlu drží hodnocení kolem 4,7 hvězdy a patří k nejoblíbenějším podnikům města. Ideální oběd před vyjížďkou na Slea Head nebo po návratu z Conor Passu.', 52.1405, -10.268, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dingle%20from%20the%20harbour%20-%20geograph.org.uk%20-%208282656.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dingle%20from%20the%20harbour%20-%20geograph.org.uk%20-%208282656.jpg"}'::text[], 5);
  insert into public.routes
