  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Healy Pass', 'Nejlepší motorkářská silnice jihozápadního Irska: R574 se serpentinami šplhá do sedla mezi hrabstvími Cork a Kerry, dole se leskne jezero Glanmore Lough. Zatáčka střídá zatáčku jako v Alpách, jen v miniaturním irském měřítku a s minimem provozu. Na vrcholu je odstavná plocha na fotku, kterou budete posílat všem.', 51.7519, -9.7345, 'https://commons.wikimedia.org/wiki/Special:FilePath/Healy%20Pass%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Healy%20Pass%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Beara%20Peninsula%20Healy%20Pass%201996%2008%2014.jpg"}'::text[], 0),
    (v_route, 'Kamenný kruh Dereenataggart', 'Bronzový kamenný kruh nad Castletownbere, starý zhruba tři tisíce let, s výhledem na záliv Bantry Bay. Stojí kousek od hlavní silnice a je volně přístupný — tichá keltská mystika bez turistických davů. Krátká odbočka, která dodá okruhu po Bearě historickou hloubku.', 51.6553, -9.9219, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dereenataggart%20Stone%20Circle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dereenataggart%20Stone%20Circle.jpg"}'::text[], 1),
    (v_route, 'Restaurace: MacCarthy''s Bar (Castletownbere)', 'Legendární pub v rybářském přístavu Castletownbere, který se dostal i na obálku slavného bestselleru Peta McCarthyho. Vpředu funguje jako krámek, vzadu se čepuje Murphy''s a servírují se čerstvé sendviče s kraby z místní flotily. Autentické západoirské zastavení s výborným hodnocením — přesně to pravé v polovině okruhu.', 51.6512, -9.9105, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dereenataggart%20Stone%20Circle.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dereenataggart%20Stone%20Circle.jpg"}'::text[], 2),
    (v_route, 'Lanovka na Dursey Island', 'Jediná kabinová lanovka v Irsku houpavě překonává úžinu Dursey Sound na ostrov, kde žije víc ovcí než lidí. Původně vozila i dobytek, dnes hlavně turisty a pár místních. I když se na ostrov nevydáte, samotný konec světa na špici Beary s výhledem na skály Bull Rock stojí za dojezd.', 51.6086, -10.2016, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dursey%20Island%20Cable%20Car%2009%202015%2009%2002.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dursey%20Island%20Cable%20Car%2009%202015%2009%2002.jpg"}'::text[], 3),
    (v_route, 'Allihies', 'Bývalá hornická vesnice s pestrobarevnými domky nad písečnou zátokou Ballydonegan — písek tu vznikl drcením rudy z měděných dolů, jejichž komíny dodnes trčí na svazích. Muzeum mědi připomíná časy, kdy odsud horníci odcházeli až na Aljašku. Jedna z nejmalebnějších zastávek celé trasy.', 51.641, -10.044, 'https://commons.wikimedia.org/wiki/Special:FilePath/Allihies%20view.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Allihies%20view.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Engine%20House%20Allihies%20Copper%20Mine%20County%20Cork%20Jun08%20DSC00429.jpg"}'::text[], 4),
    (v_route, 'Eyeries', 'Snad nejbarevnější vesnice Irska: řada domků natřených všemi odstíny duhy nad zálivem Coulagh Bay. Pravidelně vyhrává soutěže o nejupravenější obec a filmaři si ji oblíbili jako kulisu. Ideální na krátkou fotopauzu a kávu na hlavní (a jediné) ulici.', 51.687, -9.95, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eyeries%20Painted%20Houese.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eyeries%20Painted%20Houese.jpg"}'::text[], 5),
    (v_route, 'Kenmare', 'Elegantní městečko na šíji mezi poloostrovy Beara a Iveragh, plné barevných fasád, krajkářské tradice a skvělých restaurací. Trojúhelníkové centrum s ulicí Henry Street je ideální na závěrečnou večeři po okruhu. Odtud se dá druhý den pokračovat na sever do Killarney nebo na západ na Ring of Kerry.', 51.88, -9.583, 'https://commons.wikimedia.org/wiki/Special:FilePath/Henry%20Street,%20Kenmare.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Henry%20Street,%20Kenmare.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lahinch', 'Surfařská metropole západního Irska s dlouhou písečnou pláží a promenádou, na které se v létě potkávají neopreny s motorkářskými kombinézami. Slavné golfové hřiště patří k nejstarším v zemi. Dobrá první zastávka na kávu s výhledem na atlantické vlny.', 52.933, -9.348, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lahinch%20seafront%20-%20geograph.org.uk%20-%201083040.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lahinch%20seafront%20-%20geograph.org.uk%20-%201083040.jpg"}'::text[], 0),
    (v_route, 'Cliffs of Moher', 'Nejnavštěvovanější přírodní památka Irska: osm kilometrů kolmých útesů spadajících až 214 metrů do Atlantiku, s věží O''Brien''s Tower na nejvyšším bodě. Za jasného dne dohlédnete na Aranské ostrovy i hory Connemary, kolem krouží papuchalci. Motorka platí na parkovišti u návštěvnického centra méně než auto; přijeďte brzy ráno, vyhnete se davům.', 52.9715, -9.4265, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cliffs%20of%20Moher,%20County%20Clare,%20Ireland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cliffs%20of%20Moher,%20County%20Clare,%20Ireland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cliffs%20of%20Moher,%20Irland.jpg"}'::text[], 1),
    (v_route, 'Restaurace: Gus O''Connor''s Pub (Doolin)', 'Proslulý pub z roku 1832 ve vesničce Doolin, světové metropoli irské lidové hudby. Vyhlášený seafood chowder, čerstvé ryby a večer živé „trad session" — hodnocení kolem 4,5 hvězdy a pověst, která sem táhne muzikanty z celého světa. Perfektní oběd mezi útesy a Burrenem.', 53.0125, -9.39, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fisherstreet%20Doolin%20Ireland%202005.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fisherstreet%20Doolin%20Ireland%202005.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Village%20of%20Doolin%20(Dulain),%20Co.%20Clare%20-%20geograph.org.uk%20-%20250583.jpg"}'::text[], 2),
    (v_route, 'Burren a Corkscrew Hill', 'Kraj Burren je jedna z největších krasových plošin Evropy — šedé vápencové desky, ve spárách vzácné alpské i středomořské květiny a všude pravěké památky. Serpentina Corkscrew Hill na N67 nad Ballyvaughanem nabízí sérii vraceček s výhledem na záliv Galway. Jedinečná krajina, kterou jinde v Irsku nenajdete.', 53.085, -9.166, 'https://commons.wikimedia.org/wiki/Special:FilePath/The%20Burren.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Burren.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Burren%20National%20Park.jpg"}'::text[], 3),
    (v_route, 'Dunguaire Castle', 'Věžový hrad ze 16. století na skalce nad zátokou u městečka Kinvara — údajně nejfotografovanější hrad Irska, zrcadlící se za přílivu v hladině. V létě se tu pořádají středověké bankety. Fotka z protějšího břehu s hradem nad mořem je povinnost.', 53.1425, -8.9257, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dungory%20Castle%20-%20geograph.org.uk%20-%20887251.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dungory%20Castle%20-%20geograph.org.uk%20-%20887251.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ireland%20banner-Dunguaire%20Castle%20and%20the%20lake%20in%20summer.jpg"}'::text[], 4),
    (v_route, 'Dolmen Poulnabrone', 'Portálová hrobka stará skoro šest tisíc let — starší než pyramidy — stojící uprostřed holé vápencové plošiny Burrenu. Ikonická silueta dolmenu proti nebi je jedním ze symbolů Irska. Volně přístupné pár kroků od silnice R480, ideální krátká zastávka na cestě zpět do Ennisu.', 53.0486, -9.1401, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poulnabrone-dolmen.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poulnabrone-dolmen.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Paulnabrone.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Derryclare Lough', 'Jezero pod horami Twelve Bens s nejfotografovanějším ostrůvkem borovic v Irsku — pohlednicový záběr Connemary, který znáte z kalendářů. Vyhlídka je přímo u silnice R341 poblíž vesnice Recess. Ráno bývá hladina klidná a zrcadlí celé pohoří.', 53.477, -9.766, 'https://commons.wikimedia.org/wiki/Special:FilePath/Derryclare%20Lough,%20Twelve%20Bens.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Derryclare%20Lough,%20Twelve%20Bens.jpg"}'::text[], 0),
    (v_route, 'Clifden', '„Hlavní město" Connemary s barevnými fasádami a dvěma kostelními věžemi mezi horami a mořem. Nedaleko přistáli Alcock a Brown po prvním přeletu Atlantiku v roce 1919. Dobré místo na tankování — dál na sever už jsou pumpy vzácné.', 53.489, -10.02, 'https://commons.wikimedia.org/wiki/Special:FilePath/Clifden,%20Market%20street.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Clifden,%20Market%20street.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Clifden%20Castle.jpg"}'::text[], 1),
    (v_route, 'Sky Road', 'Jedenáctikilometrový vyhlídkový okruh nad Clifdenem, který stoupá vysoko nad zátoku a ostrovy — při západu slunce jedna z nejkrásnějších silnic Irska. Úzká jednostopá asfaltka se doporučuje projet po směru hodinových ručiček. Na vrcholu je parkoviště s výhledem na otevřený Atlantik.', 53.497, -10.079, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sky%20Road%20Clifden.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sky%20Road%20Clifden.jpg"}'::text[], 2),
    (v_route, 'Kylemore Abbey', 'Pohádkové novogotické opatství zrcadlící se v hladině jezera pod zalesněným svahem — nejfotografovanější stavba západního Irska. Postavil ho v 19. století Mitchell Henry jako důkaz lásky své ženě, dnes tu sídlí benediktinky. K areálu patří viktoriánská zahrada za hradbami a kavárna.', 53.5613, -9.8886, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kylemore%20Abbey2007.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kylemore%20Abbey2007.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kylemore%20Abbey%20Reflections.jpg"}'::text[], 3),
    (v_route, 'Fjord Killary Harbour', 'Jediný fjord Irska: šestnáct kilometrů dlouhý zářez mezi horami Mweelrea a Maumturks, po hladině šňůry bójí mušlových farem. Silnice N59 kopíruje jižní břeh a nabízí jeden výhled za druhým, u ústí řeky hučí vodopád Aasleagh Falls. Za odlivu je fjord jak norská pohlednice přenesená do Irska.', 53.61, -9.74, 'https://commons.wikimedia.org/wiki/Special:FilePath/Killary%20Fjord%20(2)%20-%20geograph.org.uk%20-%205525763.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Killary%20Fjord%20(2)%20-%20geograph.org.uk%20-%205525763.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/AASLEAGH%20FALLS-IRELAND......%20(49985449592).jpg"}'::text[], 4),
    (v_route, 'Restaurace: Misunderstood Heron (Leenaun)', 'Kultovní food truck na břehu fjordu Killary u Leenaun — pravděpodobně nejkrásněji položené rychlé občerstvení v Irsku. Mušle přímo z fjordu, chobotnice, skvělé polévky a koláče; hodnocení atakuje 4,8 hvězdy a fronta se tu stojí ráda. Otevřeno v sezóně, jídlo se jí na lavičkách s výhledem na hory.', 53.6067, -9.7167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Killary%20harbour%20-%20geograph.org.uk%20-%201037296.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Killary%20harbour%20-%20geograph.org.uk%20-%201037296.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lough Tay (Guinness Lake)', 'Tmavé jezero v hlubokém údolí pod skalní stěnou Luggala, kterému se říká Guinness Lake — patřilo rodině Guinnessů a bílá pláž s černou vodou připomíná sklenici stoutu. Kulisu si zamilovali filmaři, natáčel se tu seriál Vikingové. Vyhlídka je přímo u R759 kousek nad křižovatkou s Military Road.', 53.106, -6.256, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lough%20Tay%20(Guinness%20Lake)%20Wicklow%20Mountains%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lough%20Tay%20(Guinness%20Lake)%20Wicklow%20Mountains%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Luggala%20and%20Lough%20Tay,%20Wicklow,%20Ireland.jpg"}'::text[], 0),
    (v_route, 'Sally Gap', 'Křižovatka uprostřed ničeho: sedlo na Military Road, kterou Britové postavili roku 1800 kvůli honům na povstalce. Kolem jen vřes, rašelina a nebe — nejopuštěnější kus krajiny na dohled od Dublinu. Odtud vede nejhezčí úsek R115 na jih kolem Glenmacnassu.', 53.1372, -6.3076, 'https://commons.wikimedia.org/wiki/Special:FilePath/Scarr%20Mountain,%20Wicklow.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Scarr%20Mountain,%20Wicklow.jpg"}'::text[], 1),
    (v_route, 'Vodopád Glenmacnass', 'Řeka Glenmacnass tu sklouzává po žulových deskách do hlubokého údolí — vodopád je vidět přímo ze silnice R115, která se podél něj serpentinou spouští dolů k Laraghu. Po dešti je podívaná nejlepší. Pozor na mokré kamení, pokud se vydáte blíž.', 53.048, -6.335, 'https://commons.wikimedia.org/wiki/Special:FilePath/Glenmacnass%20waterfall%20from%20the%20south%20-%20geograph.org.uk%20-%2064540.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Glenmacnass%20waterfall%20from%20the%20south%20-%20geograph.org.uk%20-%2064540.jpg"}'::text[], 2),
    (v_route, 'Glendalough', 'Klášterní město sv. Kevina ze 6. století v údolí dvou jezer: třicetimetrová kruhová věž, kamenné kostelíky a hřbitov s keltskými kříži mezi zalesněnými svahy. Jedno z duchovních center středověké Evropy a dnes nejnavštěvovanější místo hrabství Wicklow. Krátká procházka k hornímu jezeru stojí za protažení nohou.', 53.01, -6.327, 'https://commons.wikimedia.org/wiki/Special:FilePath/Glendalough%20Round%20Tower.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Glendalough%20Round%20Tower.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Round%20tower%20of%20Glendalough.jpg"}'::text[], 3),
    (v_route, 'Restaurace: The Wicklow Heather (Laragh)', 'Rodinná restaurace v Laraghu kousek od Glendalough, proslulá poctivou irskou kuchyní z lokálních surovin — jehněčí z Wicklow, čerstvý pstruh i nedělní roast. Hodnocení kolem 4,5 hvězdy, uvnitř knihovna s prvními vydáními irských klasiků. Nejlepší oběd v celých horách Wicklow.', 53.008, -6.301, 'https://commons.wikimedia.org/wiki/Special:FilePath/Glendasan%20River,%20Wicklow%20Mountains.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Glendasan%20River,%20Wicklow%20Mountains.jpg"}'::text[], 4),
    (v_route, 'Přehrada Poulaphouca (Blessington)', 'Rozlehlá vodní nádrž na řece Liffey u Blessingtonu, které místní říkají Blessington Lakes — zásobárna vody pro Dublin obklopená lesy a zálivy. Silnice kolem západního břehu nabízí klidné zatáčky a výhledy na hladinu s horami v zádech. Příjemné zklidnění na závěr horského okruhu.', 53.144, -6.523, 'https://commons.wikimedia.org/wiki/Special:FilePath/Poulaphouca%20Reservoir,%20County%20Kildare%20-%20geograph.org.uk%20-%201807100.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Poulaphouca%20Reservoir,%20County%20Kildare%20-%20geograph.org.uk%20-%201807100.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Killybegs', 'Největší rybářský přístav Irska: mola plná oceánských trawlerů, křik racků a vůně moře. Ve městě dostanete nejčerstvější ryby široko daleko a naposledy tu pořádně natankujete. Odtud začíná nejhezčí úsek pobřežní R263 na západ.', 54.634, -8.449, 'https://commons.wikimedia.org/wiki/Special:FilePath/Killybegs%20Harbour%202007%2008%2021.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Killybegs%20Harbour%202007%2008%2021.jpg"}'::text[], 0),
    (v_route, 'Útesy Slieve League', 'Jedny z nejvyšších mořských útesů Evropy — hora Slieve League padá z 601 metrů přímo do Atlantiku. Z vyhlídky Bunglass se stěna barví okrovou, rezavou a šedou a pod ní se tříští oceán; hřebenová stezka One Man''s Pass je jen pro otrlé pěší. Strmou přístupovou silničku k vyhlídce si na motorce užijete, jen u samootvíracích bran jezděte krokem.', 54.628, -8.681, 'https://commons.wikimedia.org/wiki/Special:FilePath/Slieve%20League-cliffs.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slieve%20League-cliffs.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slieve%20League%20(15919171422).jpg"}'::text[], 1),
    (v_route, 'Glengesh Pass', 'Horský průsmyk mezi Glencolmcille a Ardarou s dvojicí alpských vraceček nad ledovcovým údolím — nejfotogeničtější silnice Donegalu. Z vyhlídky na vrcholu vidíte celou stuhu asfaltu, jak se spouští mezi zelené svahy. Sjezd je prudký a úzký, brzděte s předstihem.', 54.7285, -8.532, 'https://commons.wikimedia.org/wiki/Special:FilePath/Glengesh%20Pass%20ouest.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Glengesh%20Pass%20ouest.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Glacial%20Valley%20Ardara%20Glengesh%20Pass.jpg"}'::text[], 2),
    (v_route, 'Restaurace: Nancy''s Bar (Ardara)', 'Pub v Ardaře vedený jednou rodinou už sedm generací — malé místnosti jako v obýváku, rašelina v krbu a věhlasný seafood chowder s domácím chlebem. Pravidelně se objevuje v žebříčcích nejlepších irských hospod, hodnocení kolem 4,7 hvězdy. Ardara je zároveň centrum tkaní donegalského tvídu.', 54.767, -8.409, 'https://commons.wikimedia.org/wiki/Special:FilePath/Front%20Street%20Ardara,%20Co%20Donegal.%20-%20geograph.org.uk%20-%20135931.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Front%20Street%20Ardara,%20Co%20Donegal.%20-%20geograph.org.uk%20-%20135931.jpg"}'::text[], 3),
    (v_route, 'Vodopád Assaranca', 'Vodopád padající z převisu rovnou u silničky z Ardary k pláži Maghera — zastavíte doslova pět metrů od vody. Po dešti hřmí, za sucha je to romantický závoj; hned za ním pokračuje cesta k jeskyním a dunám Maghery. Krátká odbočka, kterou většina návštěvníků Donegalu mine.', 54.742, -8.463, 'https://commons.wikimedia.org/wiki/Special:FilePath/ASSARANCA%20WATERFALL-DONEGAL.....%20(50472493402).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/ASSARANCA%20WATERFALL-DONEGAL.....%20(50472493402).jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Croagh Patrick (Murrisk)', 'Posvátná hora Irska (764 m) s dokonale kuželovitou siluetou, na kterou podle legendy vystoupil sv. Patrik a odkud vyhnal z ostrova hady. Od parkoviště v Murrisku je nejhezčí pohled na horu i na záliv Clew Bay s roztroušenými ostrůvky. Poslední červencovou neděli sem poutníci stoupají i bosí.', 53.783, -9.641, 'https://commons.wikimedia.org/wiki/Special:FilePath/Wall%20under%20Croagh%20Patrick.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wall%20under%20Croagh%20Patrick.JPG"}'::text[], 0),
    (v_route, 'Mulranny – vyhlídka na Clew Bay', 'Vesnice na šíji mezi zálivy Clew Bay a Blacksod, odkud se otevírá slavné panorama stovek zatopených drumlinů — kopečků, které vypadají jako hejno velryb v zálivu. Silnice N59 tudy vede po okraji svahu s výhledy na obě strany. Ideální fotopauza před nájezdem na Achill.', 53.904, -9.784, 'https://commons.wikimedia.org/wiki/Special:FilePath/Clew%20Bay%20001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Clew%20Bay%20001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Drowned%20drumlin%20in%20Clew%20Bay.jpg"}'::text[], 1),
    (v_route, 'Atlantic Drive (Achill)', 'Okružní silnička po jižním pobřeží Achillu: asfalt přilepený ke skále, pod vámi bílá pěna Atlantiku a naproti věžový hrad pirátské královny Grace O''Malley u Kildavnetu. Krátký, ale intenzivní úsek, kde se nebudete stačit divit. Za silného větru jeďte opatrně, poryvy od moře umí zatlačit do protisměru.', 53.89, -9.943, 'https://commons.wikimedia.org/wiki/Special:FilePath/Atlantic%20Drive.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Atlantic%20Drive.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Achill%20Head.%20Co.%20Mayo%20Ireland.jpg"}'::text[], 2),
    (v_route, 'Keem Bay', 'Tyrkysová zátoka s bílým pískem sevřená útesy na samém konci ostrova — pravidelně se objevuje v žebříčcích nejkrásnějších pláží světa a natáčeli tu oscarové Víly z Inisherinu. Silnice ke Keem stoupá po hraně útesu nad mořem: krátký, nezapomenutelný a mírně adrenalinový dojezd. Dolů k pláži vede prudké klesání, brzděte včas.', 53.967, -10.194, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keem%20Bay,%20Achill%20Island,%20Ireland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Keem%20Bay,%20Achill%20Island,%20Ireland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Keem%20Bay,%20Achill%20Island%20Co.%20Mayo,%20Ireland%20-%20geograph.org.uk%20-%20683771.jpg"}'::text[], 3),
    (v_route, 'Opuštěná vesnice Slievemore', 'Řada kamenných ruin téměř stovky domů na svahu hory Slievemore — vesnice opuštěná v době velkého hladomoru 19. století. Tiché, melancholické místo s výhledem na záliv, které vypráví o irské historii víc než učebnice. Přístup po úzké cestě kolem hřbitova, pár minut od Keelu.', 53.9946, -10.098, 'https://commons.wikimedia.org/wiki/Special:FilePath/Deserted%20Village%20at%20Slievemore.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Deserted%20Village%20at%20Slievemore.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slievemore%20Deserted%20Village%20-%20geograph.org.uk%20-%207217474.jpg"}'::text[], 4),
    (v_route, 'Restaurace: The Beehive (Keel)', 'Oblíbená rodinná restaurace a řemeslný obchod v Keelu s výhledem na pláž a útesy Minaun. Domácí polévky, čerstvý losos, koláče a scony s marmeládou — jednoduché, poctivé a s hodnocením kolem 4,5 hvězdy nejlepší zastávka na ostrově. Po obědě si projděte tříkilometrovou pláž přímo pod terasou.', 53.9727, -10.0873, 'https://commons.wikimedia.org/wiki/Special:FilePath/Keel%20beach%20achill%20island.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Keel%20beach%20achill%20island.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Achill%20Island%20-%20Keel%20-%20Beehive%20Coffee%20Shop%20%5E%20Crafts%20-%20Stop%20for%20Lunch%20-%20geograph.org.uk%20-%203758140.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Drumcliff a Benbulbin', 'Stolová hora Benbulbin (526 m) s dramaticky zvrásněnými boky je poznávacím znamením Sliga — irský „Table Mountain". Pod ní v Drumcliffu leží u kostelíka hrob básníka W. B. Yeatse s proslulým epitafem „Cast a cold eye on life, on death". Výhled na horu přímo od silnice N15, zastávka na pět minut i na hodinu.', 54.327, -8.497, 'https://commons.wikimedia.org/wiki/Special:FilePath/Benbulbenmount.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Benbulbenmount.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Yeats%20Grave%20Drumcliffe%20Sligo.jpg"}'::text[], 0),
    (v_route, 'Strandhill', 'Surfařská vesnice pod horou Knocknarea, na jejímž vrcholu je mohyla legendární královny Maeve. Vlny tu patří k nejlepším v Irsku (koupání je kvůli proudům zakázané, surfuje se s instruktorem) a promenáda s kavárnami žije celý den. Atmosféra půl Kalifornie, půl Irska.', 54.27, -8.596, 'https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Strandhill%20(cropped).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Strandhill%20(cropped).jpg"}'::text[], 1),
    (v_route, 'Restaurace: Shells Café (Strandhill)', 'Kultovní kavárna přímo na promenádě ve Strandhillu: domácí pečivo, vydatné brunche a nejlepší káva na severozápadě, to vše s výhledem na surfaře. Hodnocení kolem 4,5 hvězdy a vlastní kuchařky, které si odvážejí i turisté. Ideální druhá snídaně před dlouhým pobřežním úsekem na západ.', 54.2703, -8.5972, 'https://commons.wikimedia.org/wiki/Special:FilePath/Strandhill2.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Strandhill2.jpg"}'::text[], 2),
    (v_route, 'Downpatrick Head (Dún Briste)', 'Padesátimetrový osamělý skalní sloup Dún Briste („zlomená pevnost") stojí pár desítek metrů od útesů — od pevniny ho odtrhla bouře roku 1393 i s lidmi, které pak zachraňovali po lanech. Na mysu je i dýchající puklina Poll na Seantoine, ohrazená kvůli bezpečnosti. Jedno z nejpůsobivějších míst celé Wild Atlantic Way, deset minut od silnice R314.', 54.326, -9.348, 'https://commons.wikimedia.org/wiki/Special:FilePath/Dun%20Briste,%20Downpatrick%20Head.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Dun%20Briste,%20Downpatrick%20Head.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Downpatrick%20Head%202021.jpg"}'::text[], 3),
    (v_route, 'Céide Fields', 'Nejrozsáhlejší neolitická památka světa: pod vrstvou rašeliny se skrývá systém kamenných zídek a polí starý přes pět tisíc let. Pyramidové návštěvnické centrum stojí na hraně 110metrových útesů s výhledem na otevřený Atlantik. Důstojná tečka za trasou — dál na západ už pokračuje jen prázdná R314 do Belmulletu.', 54.308, -9.456, 'https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A9ide%20fields.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A9ide%20fields.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ceide%20Fields%20Visitor%20Centre%20-%20geograph.org.uk%20-%20486592.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Bantry a Bantry House', 'Přístavní městečko na konci hlubokého zálivu Bantry Bay, kam se roku 1796 pokusila (marně) vylodit francouzská flotila s irskými revolucionáři. Georgiánské sídlo Bantry House s italskými zahradami a výhledem na záliv patří k nejkrásnějším v Irsku. V pátek žije náměstí trhem s lokálními sýry a rybami.', 51.68, -9.454, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bantry%20From%20above.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bantry%20From%20above.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fountain%20at%20Bantry%20House.jpg"}'::text[], 0),
    (v_route, 'Sheep''s Head – konec poloostrova', 'Nejužší a nejtišší z jihozápadních poloostrovů: jednostopá silnička končí na parkovišti u kavárny Bernie''s Cupán Tae a dál už jen pěšina k maličkému majáku na útesu. Cestou po hřebeni vidíte současně zálivy Bantry i Dunmanus. Okruh Goat''s Path po severní straně je motorkářská meditace — jen vy, ovce a Atlantik.', 51.5425, -9.8477, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sheep%27s%20Head%20-%20end%20of%20the%20peninsula%20-%20geograph.org.uk%20-%206008888.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sheep%27s%20Head%20-%20end%20of%20the%20peninsula%20-%20geograph.org.uk%20-%206008888.jpg"}'::text[], 1),
    (v_route, 'Mizen Head', 'Nejjihozápadnější bod Irska: stanice signální služby na skalním ostrově, spojená s pevninou obloukovým mostem nad soutěskou, kde se vlny tříští o břidlicové stěny a dole odpočívají tuleni. Expozice připomíná Marconiho telegrafní pokusy i ztroskotané lodě. Vstupné se platí v návštěvnickém centru, k mostu se schází po schodech — výhledy stojí za každý krok.', 51.4499, -9.81, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mizen%20Head.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mizen%20Head.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Mizen%20Head%20Bridge%20-%20geograph.org.uk%20-%2012656.jpg"}'::text[], 2),
    (v_route, 'Restaurace: O''Sullivan''s Bar (Crookhaven)', 'Pub na molu v Crookhavenu, kde se pinta pije s nohama nad vodou přístavu — v létě sem připlouvají jachty z půlky Evropy. Vyhlášené krabí sendviče a chowder z denního úlovku, hodnocení kolem 4,6 hvězdy. Kdysi tu na poštu čekávaly transatlantické parníky, dnes je to nejpohodovější zastávka West Corku.', 51.472, -9.728, 'https://commons.wikimedia.org/wiki/Special:FilePath/O%27Sullivan%27s%20Bar,%20Crookhaven%20-%20geograph.org.uk%20-%20243220.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/O%27Sullivan%27s%20Bar,%20Crookhaven%20-%20geograph.org.uk%20-%20243220.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Crookhaven,%20Co.%20Cork,%20Ireland%20-%20panoramio.jpg"}'::text[], 3),
    (v_route, 'Schull', 'Živé přístavní městečko pod horou Mount Gabriel s gurmánskou pověstí: sýrárny, pekárny, nedělní trh a hospůdky plné jachtařů. Z přístavu vyplouvají lodě k majáku Fastnet, nejjižnějšímu bodu Irska. Příjemná předposlední zastávka před návratem do Bantry přes Ballydehob.', 51.526, -9.546, 'https://commons.wikimedia.org/wiki/Special:FilePath/Schull%20main%20street.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Schull%20main%20street.jpg"}'::text[], 4);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Gap of Mamore', 'Sedlo mezi kopci Urris Hills se stoupáním, které patří k nejprudším asfaltům Irska — serpentiny se sklonem přes 30 % a u vrcholu poutní studánka sv. Eigne ověšená růženci. Z vrcholu padá výhled na pláž Tullagh a otevřený oceán. Krátké, prudké, nezapomenutelné; za mokra jeďte s rezervou, výhybny jsou malé.', 55.2379, -7.4664, 'https://commons.wikimedia.org/wiki/Special:FilePath/A%20View%20From%20Mamore%20Gap%20-%20panoramio.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/A%20View%20From%20Mamore%20Gap%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Road%20leading%20to%20the%20Gap%20Of%20Mamore%20-%20geograph.org.uk%20-%20400401.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Nancy''s Barn (Ballyliffin)', 'Bistro v kamenné stodole v golfovém Ballyliffinu, jehož rybí chowder vyhrál titul mistra světa na šampionátu v Newportu v USA. K tomu domácí chleba, koláče a pořádná káva; hodnocení se drží kolem 4,7 hvězdy. Ideální oběd před finálním dojezdem na Malin Head.', 55.276, -7.391, 'https://commons.wikimedia.org/wiki/Special:FilePath/Strand%20Hotel,%20Ballyliffin,%20Co.%20Donegal%20-%20geograph.org.uk%20-%201384902.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Strand%20Hotel,%20Ballyliffin,%20Co.%20Donegal%20-%20geograph.org.uk%20-%201384902.jpg"}'::text[], 1),
    (v_route, 'Malin Head (Banba''s Crown)', 'Nejsevernější bod Irska: věž staré signální stanice z roku 1805, pod útesem obří nápis ÉIRE 80 vyskládaný za války z bílých kamenů pro piloty a výhled, který za jasného dne sahá až ke Skotsku. Právě odsud začínají (nebo končí) všechny přejezdy Irska „od Malinu k Mizenu". Natáčely se tu i Star Wars; večer je to jedno z nejlepších míst na polární záři v Irsku.', 55.382, -7.373, 'https://commons.wikimedia.org/wiki/Special:FilePath/80%20Eire%20at%20Malin%20Head.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/80%20Eire%20at%20Malin%20Head.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Raised%20beaches%20at%20Malin%20Head%20-%20panoramio.jpg"}'::text[], 2),
    (v_route, 'Kinnagoe Bay', 'Skrytá pláž na východním pobřeží Inishowenu, kam vede prudká lesní silnička — zlatý písek, zelené svahy a obvykle ani noha. V roce 1588 tu ztroskotala loď španělské Armady La Trinidad Valencera; artefakty z vraku vystavuje muzeum v Derry. Odměna pro ty, kdo neodbočí zkratkou domů.', 55.257, -7.115, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kinnagoe%20Bay,%20Inishowen,%20Co%20Donegal%20-%20geograph.org.uk%20-%2083440.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kinnagoe%20Bay,%20Inishowen,%20Co%20Donegal%20-%20geograph.org.uk%20-%2083440.jpg"}'::text[], 3),
    (v_route, 'Grianán of Aileach', 'Mohutná kruhová kamenná pevnost na vrcholu kopce (244 m) nad soutokem zálivů Lough Swilly a Lough Foyle, sídlo severních králů dynastie Uí Néill. Zdi silné čtyři metry, uvnitř terasy s ochozy a kolem dokola výhled na půl Ulsteru. K pevnosti vede zábavná točitá silnička — důstojné finále celého okruhu.', 54.989, -7.428, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grianan%20of%20Aileach%20Donegal.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grianan%20of%20Aileach%20Donegal.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grainan%20of%20Aileach%20Ring%20Fort%20-%20Donegal%20-%20Ireland.jpg"}'::text[], 4);
