-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — IRSKO (10 tras, sort_order 4310–4400)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Irsko – poloostrov Dingle a Slea Head Drive
  delete from public.routes where name = 'Irsko – poloostrov Dingle a Slea Head Drive' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – poloostrov Dingle a Slea Head Drive', 'Okruh po nejzápadnějším poloostrově Irska kombinuje slavnou pobřežní silnici Slea Head Drive (R559) s dramatickým průsmykem Conor Pass, nejvyšší horskou silnicí v zemi. Úzká asfaltka se vine těsně nad Atlantikem kolem útesů, keltských pevností a výhledů na Blasketovy ostrovy, zpáteční cesta přidá dlouhou písečnou kosu Inch. Pozor: v Irsku se jezdí VLEVO — na jednosměrně doporučeném okruhu (po směru hodinových ručiček) se vyhnete couvání před autobusy. Nejlepší od května do září; počítejte s větrem, mlhou na Conor Passu, ovcemi na vozovce a úseky širokými sotva na jedno auto. Barevné městečko Dingle je ideální základna na kávu i čerstvé ryby.', 'loop', 135, 240, 'medium',
     '[{"lat": 52.1409, "lng": -10.264, "label": "Start: Dingle"}, {"lat": 52.0975, "lng": -10.4467, "label": "Slea Head"}, {"lat": 52.1247, "lng": -10.4603, "label": "Přístaviště Dunquin"}, {"lat": 52.1727, "lng": -10.3517, "label": "Gallarus Oratory"}, {"lat": 52.1596, "lng": -10.2038, "label": "Conor Pass"}, {"lat": 52.141, "lng": -9.977, "label": "Pláž Inch"}, {"lat": 52.1409, "lng": -10.264, "label": "Cíl: Dingle"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=52.1409,-10.264&destination=52.1409,-10.264&travelmode=driving&waypoints=52.0975,-10.4467%7C52.1247,-10.4603%7C52.1727,-10.3517%7C52.1596,-10.2038%7C52.141,-9.977', 'https://commons.wikimedia.org/wiki/Special:FilePath/Slea%20Head,%20Ireland.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Slea%20Head,%20Ireland.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A9%20Dh%C3%BAn%20Chaoin%20Dunquin%20Pier.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gallarus%20Oratory.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Dingle%20Conor%20Pass.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Beach%20at%20Inch%20in%20Dingle%20Bay%20Kerry%20Ireland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dingle%20from%20the%20harbour%20-%20geograph.org.uk%20-%208282656.jpg"}'::text[], '{"Slea Head","Přístaviště Dunquin","Gallarus Oratory","Průsmyk Conor Pass","Pláž Inch","Restaurace: The Fish Box (Dingle)"}'::text[], '{"IE"}'::text[], false, 4310, 'approved');

  -- Irsko – poloostrov Beara a Healy Pass
  delete from public.routes where name = 'Irsko – poloostrov Beara a Healy Pass' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – poloostrov Beara a Healy Pass', 'Divočejší a prázdnější soused slavného Ring of Kerry: okruh Ring of Beara nabízí serpentiny průsmyku Healy Pass, jedinou lanovku v Irsku na ostrov Dursey a barevné vesničky Allihies a Eyeries. Silnice R571 a R572 jsou úzké, zvlněné a téměř bez provozu — ráj pro motorkáře, kteří chtějí Atlantik jen pro sebe. Nezapomeňte, že se jezdí VLEVO, a v zatáčkách počítejte s ovcemi a traktory. Povrch je místy hrubý a záplatovaný, ideální sezóna květen až září. Start i cíl v elegantním městečku Kenmare s výbornými restauracemi.', 'loop', 150, 250, 'medium',
     '[{"lat": 51.88, "lng": -9.583, "label": "Start: Kenmare"}, {"lat": 51.7519, "lng": -9.7345, "label": "Healy Pass"}, {"lat": 51.651, "lng": -9.911, "label": "Castletownbere"}, {"lat": 51.6086, "lng": -10.2016, "label": "Lanovka Dursey Island"}, {"lat": 51.641, "lng": -10.044, "label": "Allihies"}, {"lat": 51.687, "lng": -9.95, "label": "Eyeries"}, {"lat": 51.88, "lng": -9.583, "label": "Cíl: Kenmare"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.88,-9.583&destination=51.88,-9.583&travelmode=driving&waypoints=51.7519,-9.7345%7C51.651,-9.911%7C51.6086,-10.2016%7C51.641,-10.044%7C51.687,-9.95', 'https://commons.wikimedia.org/wiki/Special:FilePath/Healy%20Pass%2001.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Healy%20Pass%2001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dereenataggart%20Stone%20Circle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dereenataggart%20Stone%20Circle.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dursey%20Island%20Cable%20Car%2009%202015%2009%2002.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Allihies%20view.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Eyeries%20Painted%20Houese.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Henry%20Street,%20Kenmare.jpg"}'::text[], '{"Healy Pass","Kamenný kruh Dereenataggart","Restaurace: MacCarthy''s Bar (Castletownbere)","Lanovka na Dursey Island","Allihies","Eyeries","Kenmare"}'::text[], '{"IE"}'::text[], false, 4320, 'approved');

  -- Irsko – Cliffs of Moher a kraj Burren
  delete from public.routes where name = 'Irsko – Cliffs of Moher a kraj Burren' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – Cliffs of Moher a kraj Burren', 'Okruh hrabstvím Clare spojuje dvě naprosto odlišné tváře Irska: 200 metrů vysoké útesy Cliffs of Moher a měsíční vápencovou krajinu Burrenu. Pobřežní R477 kolem Black Head patří k nejhezčím úsekům Wild Atlantic Way — moře na jedné straně, holé šedé desky vápence na druhé. Jezdí se VLEVO; u útesů počítejte s hustým turistickým provozem a autobusy, zbytek okruhu je příjemně prázdný. Serpentina Corkscrew Hill na N67 je místní lahůdka. Nejlépe květen až září, útesy si nechte na ráno nebo podvečer, kdy je nejméně lidí.', 'loop', 150, 240, 'easy',
     '[{"lat": 52.8436, "lng": -8.986, "label": "Start: Ennis"}, {"lat": 52.933, "lng": -9.348, "label": "Lahinch"}, {"lat": 52.9715, "lng": -9.4265, "label": "Cliffs of Moher"}, {"lat": 53.014, "lng": -9.378, "label": "Doolin"}, {"lat": 53.115, "lng": -9.15, "label": "Ballyvaughan"}, {"lat": 53.1425, "lng": -8.9257, "label": "Dunguaire Castle"}, {"lat": 53.0486, "lng": -9.1401, "label": "Poulnabrone"}, {"lat": 52.8436, "lng": -8.986, "label": "Cíl: Ennis"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=52.8436,-8.986&destination=52.8436,-8.986&travelmode=driving&waypoints=52.933,-9.348%7C52.9715,-9.4265%7C53.014,-9.378%7C53.115,-9.15%7C53.1425,-8.9257%7C53.0486,-9.1401', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cliffs%20of%20Moher,%20County%20Clare,%20Ireland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lahinch%20seafront%20-%20geograph.org.uk%20-%201083040.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cliffs%20of%20Moher,%20County%20Clare,%20Ireland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fisherstreet%20Doolin%20Ireland%202005.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/The%20Burren.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dungory%20Castle%20-%20geograph.org.uk%20-%20887251.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Poulnabrone-dolmen.jpg"}'::text[], '{"Lahinch","Cliffs of Moher","Restaurace: Gus O''Connor''s Pub (Doolin)","Burren a Corkscrew Hill","Dunguaire Castle","Dolmen Poulnabrone"}'::text[], '{"IE"}'::text[], false, 4330, 'approved');

  -- Irsko – Connemara, Sky Road a fjord Killary
  delete from public.routes where name = 'Irsko – Connemara, Sky Road a fjord Killary' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – Connemara, Sky Road a fjord Killary', 'Velký okruh Connemarou, nejromantičtější divočinou Irska: rašeliniště, hory Twelve Bens, černá jezera a jediný irský fjord Killary Harbour. Silnice N59 a R341 se vlní prázdnou krajinou, vyhlídkový okruh Sky Road nad Clifdenem patří k nejkrásnějším deseti kilometrům v zemi. Jezdí se VLEVO; hlavní pozor na ovce, které tu mají absolutní přednost, a na boční vítr na otevřených blatech. Novogotické opatství Kylemore nad jezerem je povinná fotozastávka. Ideální od května do října, po dešti krajina doslova svítí.', 'loop', 190, 280, 'medium',
     '[{"lat": 53.2707, "lng": -9.0568, "label": "Start: Galway"}, {"lat": 53.477, "lng": -9.766, "label": "Derryclare Lough"}, {"lat": 53.489, "lng": -10.02, "label": "Clifden"}, {"lat": 53.497, "lng": -10.079, "label": "Sky Road"}, {"lat": 53.5613, "lng": -9.8886, "label": "Kylemore Abbey"}, {"lat": 53.594, "lng": -9.669, "label": "Leenaun – Killary"}, {"lat": 53.2707, "lng": -9.0568, "label": "Cíl: Galway"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.2707,-9.0568&destination=53.2707,-9.0568&travelmode=driving&waypoints=53.477,-9.766%7C53.489,-10.02%7C53.497,-10.079%7C53.5613,-9.8886%7C53.594,-9.669', 'https://commons.wikimedia.org/wiki/Special:FilePath/Kylemore%20Abbey2007.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Derryclare%20Lough,%20Twelve%20Bens.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Clifden,%20Market%20street.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sky%20Road%20Clifden.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kylemore%20Abbey2007.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Killary%20Fjord%20(2)%20-%20geograph.org.uk%20-%205525763.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Killary%20harbour%20-%20geograph.org.uk%20-%201037296.jpg"}'::text[], '{"Derryclare Lough","Clifden","Sky Road","Kylemore Abbey","Fjord Killary Harbour","Restaurace: Misunderstood Heron (Leenaun)"}'::text[], '{"IE"}'::text[], false, 4340, 'approved');

  -- Irsko – Wicklow Mountains a Glendalough
  delete from public.routes where name = 'Irsko – Wicklow Mountains a Glendalough' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – Wicklow Mountains a Glendalough', 'Hory kousek od Dublinu: legendární Military Road (R115) stoupá přes vřesoviště a rašeliniště národního parku Wicklow Mountains k sedlu Sally Gap a dál kolem vodopádu Glenmacnass do klášterního údolí Glendalough. Prázdná úzká silnice s výhledy na jezero Lough Tay, kde se natáčeli Vikingové i Braveheart. Jezdí se VLEVO; na blatech pozor na volně se pasoucí ovce, jeleny a vlhký povrch — v horách bývá mlha i v létě. Zpět přes sedlo Wicklow Gap a jezera u Blessingtonu. Ideální jarní nebo podzimní vyjížďka, o víkendech vyjíždějí i dublinští motorkáři.', 'loop', 145, 220, 'medium',
     '[{"lat": 53.3498, "lng": -6.2603, "label": "Start: Dublin"}, {"lat": 53.19, "lng": -6.221, "label": "Glencree"}, {"lat": 53.106, "lng": -6.256, "label": "Lough Tay"}, {"lat": 53.1372, "lng": -6.3076, "label": "Sally Gap"}, {"lat": 53.048, "lng": -6.335, "label": "Vodopád Glenmacnass"}, {"lat": 53.01, "lng": -6.327, "label": "Glendalough"}, {"lat": 53.17, "lng": -6.533, "label": "Blessington"}, {"lat": 53.3498, "lng": -6.2603, "label": "Cíl: Dublin"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.3498,-6.2603&destination=53.3498,-6.2603&travelmode=driving&waypoints=53.19,-6.221%7C53.106,-6.256%7C53.1372,-6.3076%7C53.048,-6.335%7C53.01,-6.327%7C53.17,-6.533', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lough%20Tay%20(Guinness%20Lake)%20Wicklow%20Mountains%202.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lough%20Tay%20(Guinness%20Lake)%20Wicklow%20Mountains%202.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Scarr%20Mountain,%20Wicklow.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Glenmacnass%20waterfall%20from%20the%20south%20-%20geograph.org.uk%20-%2064540.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Glendalough%20Round%20Tower.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Glendasan%20River,%20Wicklow%20Mountains.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Poulaphouca%20Reservoir,%20County%20Kildare%20-%20geograph.org.uk%20-%201807100.jpg"}'::text[], '{"Lough Tay (Guinness Lake)","Sally Gap","Vodopád Glenmacnass","Glendalough","Restaurace: The Wicklow Heather (Laragh)","Přehrada Poulaphouca (Blessington)"}'::text[], '{"IE"}'::text[], false, 4350, 'approved');

  -- Irsko – Donegal, útesy Slieve League
  delete from public.routes where name = 'Irsko – Donegal, útesy Slieve League' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – Donegal, útesy Slieve League', 'Nejdivočejší kout Irska: okruh jihozápadním Donegalem míří k útesům Slieve League, které jsou s 600 metry téměř třikrát vyšší než Cliffs of Moher — a přitom skoro bez turistů. Cestou rybářský přístav Killybegs, gaeltachtské údolí Glencolmcille a především průsmyk Glengesh Pass s alpskými vracečkami. Jezdí se VLEVO; silnice R263 a horské spojky jsou úzké, s ovcemi, sjezd z Glengeshe má prudké serpentiny. K vyhlídce Bunglass vede strmá jednostopá cesta — na motorce pohodlně, jen pozor na protijedoucí auta u bran. Nejlepší červen až září, za deště a mlhy útesy neuvidíte.', 'loop', 130, 220, 'medium',
     '[{"lat": 54.654, "lng": -8.11, "label": "Start: Donegal Town"}, {"lat": 54.634, "lng": -8.449, "label": "Killybegs"}, {"lat": 54.628, "lng": -8.681, "label": "Slieve League – Bunglass"}, {"lat": 54.708, "lng": -8.724, "label": "Glencolmcille"}, {"lat": 54.7285, "lng": -8.532, "label": "Glengesh Pass"}, {"lat": 54.767, "lng": -8.409, "label": "Ardara"}, {"lat": 54.654, "lng": -8.11, "label": "Cíl: Donegal Town"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.654,-8.11&destination=54.654,-8.11&travelmode=driving&waypoints=54.634,-8.449%7C54.628,-8.681%7C54.708,-8.724%7C54.7285,-8.532%7C54.767,-8.409', 'https://commons.wikimedia.org/wiki/Special:FilePath/Slieve%20League-cliffs.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Killybegs%20Harbour%202007%2008%2021.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Slieve%20League-cliffs.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Glengesh%20Pass%20ouest.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Front%20Street%20Ardara,%20Co%20Donegal.%20-%20geograph.org.uk%20-%20135931.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/ASSARANCA%20WATERFALL-DONEGAL.....%20(50472493402).jpg"}'::text[], '{"Killybegs","Útesy Slieve League","Glengesh Pass","Restaurace: Nancy''s Bar (Ardara)","Vodopád Assaranca"}'::text[], '{"IE"}'::text[], false, 4360, 'approved');

  -- Irsko – ostrov Achill a Atlantic Drive
  delete from public.routes where name = 'Irsko – ostrov Achill a Atlantic Drive' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – ostrov Achill a Atlantic Drive', 'Největší irský ostrov Achill je s pevninou spojený mostem, takže se na něj dá dojet po vlastní ose — a jeho okružní Atlantic Drive patří k vrcholům celé Wild Atlantic Way. Trasa z Westportu vede kolem posvátné hory Croagh Patrick a zálivu Clew Bay s údajně 365 ostrůvky, na ostrově pak k tyrkysové zátoce Keem Bay po silnici vytesané do svahu nad mořem. Jezdí se VLEVO; na Achillu počítejte se silným bočním větrem, ovcemi na vozovce a úseky bez svodidel nad útesy. Kombinace hor, plážía opuštěné vesnice Slievemore je jedinečná. Nejlépe od května do září, za bouřky Atlantic Drive raději vynechte.', 'loop', 160, 250, 'medium',
     '[{"lat": 53.801, "lng": -9.515, "label": "Start: Westport"}, {"lat": 53.783, "lng": -9.641, "label": "Murrisk – Croagh Patrick"}, {"lat": 53.904, "lng": -9.784, "label": "Mulranny"}, {"lat": 53.89, "lng": -9.943, "label": "Atlantic Drive (Achill)"}, {"lat": 53.973, "lng": -10.087, "label": "Keel"}, {"lat": 53.967, "lng": -10.194, "label": "Keem Bay"}, {"lat": 53.9946, "lng": -10.098, "label": "Slievemore"}, {"lat": 53.801, "lng": -9.515, "label": "Cíl: Westport"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=53.801,-9.515&destination=53.801,-9.515&travelmode=driving&waypoints=53.783,-9.641%7C53.904,-9.784%7C53.89,-9.943%7C53.973,-10.087%7C53.967,-10.194%7C53.9946,-10.098', 'https://commons.wikimedia.org/wiki/Special:FilePath/Keem%20Bay,%20Achill%20Island,%20Ireland.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Wall%20under%20Croagh%20Patrick.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/Clew%20Bay%20001.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Atlantic%20Drive.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Keem%20Bay,%20Achill%20Island,%20Ireland.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Deserted%20Village%20at%20Slievemore.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Keel%20beach%20achill%20island.jpg"}'::text[], '{"Croagh Patrick (Murrisk)","Mulranny – vyhlídka na Clew Bay","Atlantic Drive (Achill)","Keem Bay","Opuštěná vesnice Slievemore","Restaurace: The Beehive (Keel)"}'::text[], '{"IE"}'::text[], false, 4370, 'approved');

  -- Irsko – Sligo a Downpatrick Head
  delete from public.routes where name = 'Irsko – Sligo a Downpatrick Head' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – Sligo a Downpatrick Head', 'Pohodová etapa Wild Atlantic Way krajem básníka Yeatse: od stolové hory Benbulbin přes surfařský Strandhill po severním pobřeží Maya až ke skalnímu sloupu Dún Briste u Downpatrick Head a neolitickým polím Céide Fields. Silnice R297 a R314 se drží nízko u oceánu, provoz je minimální a výhledy nekonečné. Jezdí se VLEVO — na prázdných rovinkách na to po pauze snadno zapomenete, pozor při vyjíždění ze zastávek. Trasa je nenáročná a vhodná i pro méně zkušené; větrno bývá po celý rok. Ideální od května do září, na Downpatrick Head nechoďte za vichru až k okraji útesu.', 'poi', 130, 200, 'easy',
     '[{"lat": 54.2766, "lng": -8.4761, "label": "Start: Sligo"}, {"lat": 54.327, "lng": -8.497, "label": "Drumcliff"}, {"lat": 54.27, "lng": -8.596, "label": "Strandhill"}, {"lat": 54.288, "lng": -8.963, "label": "Easkey"}, {"lat": 54.213, "lng": -9.22, "label": "Killala"}, {"lat": 54.326, "lng": -9.348, "label": "Downpatrick Head"}, {"lat": 54.308, "lng": -9.456, "label": "Cíl: Céide Fields"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=54.2766,-8.4761&destination=54.308,-9.456&travelmode=driving&waypoints=54.327,-8.497%7C54.27,-8.596%7C54.288,-8.963%7C54.213,-9.22%7C54.326,-9.348', 'https://commons.wikimedia.org/wiki/Special:FilePath/Benbulbenmount.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Benbulbenmount.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Panorama%20Strandhill%20(cropped).jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Strandhill2.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Dun%20Briste,%20Downpatrick%20Head.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/C%C3%A9ide%20fields.jpg"}'::text[], '{"Drumcliff a Benbulbin","Strandhill","Restaurace: Shells Café (Strandhill)","Downpatrick Head (Dún Briste)","Céide Fields"}'::text[], '{"IE"}'::text[], false, 4380, 'approved');

  -- Irsko – West Cork, Mizen Head a Sheep's Head
  delete from public.routes where name = 'Irsko – West Cork, Mizen Head a Sheep''s Head' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – West Cork, Mizen Head a Sheep''s Head', 'Dva prsty pevniny na samém jihozápadě Irska: úzký poloostrov Sheep''s Head s jednou z nejopuštěnějších silniček v zemi a Mizen Head, „irský konec světa" s bílým mostem nad soutěskou plnou vln a tuleňů. Mezi nimi písečná Barleycove, jachtařský Crookhaven a gurmánský Schull. Jezdí se VLEVO; silničky na Sheep''s Head jsou jednostopé s výhybnami — buďte připraveni zastavit a pozdravit, tady zdraví každý. Provoz minimální, povrch místy hrubý, značení skromné. Ideální květen až září; za jasného dne uvidíte maják Fastnet, „slzu Irska", poslední kus vlasti, který viděli vystěhovalci do Ameriky.', 'loop', 160, 260, 'medium',
     '[{"lat": 51.68, "lng": -9.454, "label": "Start: Bantry"}, {"lat": 51.571, "lng": -9.713, "label": "Kilcrohane"}, {"lat": 51.5425, "lng": -9.8477, "label": "Sheep''s Head"}, {"lat": 51.493, "lng": -9.711, "label": "Goleen"}, {"lat": 51.4499, "lng": -9.81, "label": "Mizen Head"}, {"lat": 51.472, "lng": -9.728, "label": "Crookhaven"}, {"lat": 51.526, "lng": -9.546, "label": "Schull"}, {"lat": 51.68, "lng": -9.454, "label": "Cíl: Bantry"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=51.68,-9.454&destination=51.68,-9.454&travelmode=driving&waypoints=51.571,-9.713%7C51.5425,-9.8477%7C51.493,-9.711%7C51.4499,-9.81%7C51.472,-9.728%7C51.526,-9.546', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mizen%20Head.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bantry%20From%20above.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sheep%27s%20Head%20-%20end%20of%20the%20peninsula%20-%20geograph.org.uk%20-%206008888.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mizen%20Head.JPG","https://commons.wikimedia.org/wiki/Special:FilePath/O%27Sullivan%27s%20Bar,%20Crookhaven%20-%20geograph.org.uk%20-%20243220.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Schull%20main%20street.jpg"}'::text[], '{"Bantry a Bantry House","Sheep''s Head – konec poloostrova","Mizen Head","Restaurace: O''Sullivan''s Bar (Crookhaven)","Schull"}'::text[], '{"IE"}'::text[], false, 4390, 'approved');

  -- Irsko – Inishowen 100 a Malin Head
  delete from public.routes where name = 'Irsko – Inishowen 100 a Malin Head' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Irsko – Inishowen 100 a Malin Head', 'Značený okruh „Inis Eoghain 100" (100 mil) kolem nejsevernějšího poloostrova Irska: pevnost Fort Dunree nad zálivem Lough Swilly, poutní sedlo Gap of Mamore se sklonem přes 30 % a nakonec Malin Head — úplně nejsevernější bod ostrova s nápisem ÉIRE 80 z bílých kamenů z dob druhé světové války. Jezdí se VLEVO; stoupání na Mamore je krátké, ale extrémně prudké a jednostopé, za mokra vyžaduje jistou ruku se spojkou. Zbytek okruhu jsou širší, rytmické silnice s minimem aut a výhledy až ke skotským Hebridám. Zpáteční cestu korunuje kamenná pevnost Grianán of Aileach. Nejlépe květen až září; tady na severu počítejte s počasím všech čtyř ročních období za jeden den.', 'loop', 165, 260, 'medium',
     '[{"lat": 55.136, "lng": -7.453, "label": "Start: Buncrana"}, {"lat": 55.198, "lng": -7.556, "label": "Fort Dunree"}, {"lat": 55.2379, "lng": -7.4664, "label": "Gap of Mamore"}, {"lat": 55.276, "lng": -7.391, "label": "Ballyliffin"}, {"lat": 55.382, "lng": -7.373, "label": "Malin Head"}, {"lat": 55.257, "lng": -7.115, "label": "Kinnagoe Bay"}, {"lat": 54.989, "lng": -7.428, "label": "Grianán of Aileach"}, {"lat": 55.136, "lng": -7.453, "label": "Cíl: Buncrana"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=55.136,-7.453&destination=55.136,-7.453&travelmode=driving&waypoints=55.198,-7.556%7C55.2379,-7.4664%7C55.276,-7.391%7C55.382,-7.373%7C55.257,-7.115%7C54.989,-7.428', 'https://commons.wikimedia.org/wiki/Special:FilePath/80%20Eire%20at%20Malin%20Head.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/A%20View%20From%20Mamore%20Gap%20-%20panoramio.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Strand%20Hotel,%20Ballyliffin,%20Co.%20Donegal%20-%20geograph.org.uk%20-%201384902.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/80%20Eire%20at%20Malin%20Head.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kinnagoe%20Bay,%20Inishowen,%20Co%20Donegal%20-%20geograph.org.uk%20-%2083440.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grianan%20of%20Aileach%20Donegal.jpg"}'::text[], '{"Gap of Mamore","Restaurace: Nancy''s Barn (Ballyliffin)","Malin Head (Banba''s Crown)","Kinnagoe Bay","Grianán of Aileach"}'::text[], '{"IE"}'::text[], false, 4400, 'approved');

